input.content:
workspace "Bookshop" "A simple online bookshop" {

    model {
        customer = person "Customer" "A customer who buys books online"

        bookshop = softwareSystem "Bookshop" "An online bookshop for browsing and buying books" {
            webStore = container "Web Store" "The web application where customers browse the catalogue and place orders" "Java"
            orderProcessor = container "Order Processor" "Processes and fulfils orders placed through the web store" "Java"

            customer -> webStore "Places orders through" "HTTPS"
            webStore -> orderProcessor "Submits orders to" "gRPC"
        }
    }

    views {
        systemContext bookshop "SystemContext" "The system context view of the Bookshop" {
            include *
            autoLayout
        }
    }
}

